-- RCMExcel database, MySQL / MariaDB edition.
--
-- The platform moved from PostgreSQL to MariaDB (what Hostinger's web hosting provides) before
-- any production data existed, so the earlier PostgreSQL migrations were replaced by this one
-- baseline. They remain in the Git history.
--
-- The tables below are generated by Prisma from prisma/schema.prisma. The value ranges Prisma cannot
-- express follow at the end. The audit log's
-- append-only trigger is created by scripts/db-harden.mjs instead, because shared hosting may
-- not allow triggers; see that file.

-- CreateTable
CREATE TABLE `User` (
    `id` VARCHAR(191) NOT NULL,
    `name` MEDIUMTEXT NOT NULL,
    `email` VARCHAR(191) NOT NULL,
    `emailVerified` BOOLEAN NOT NULL DEFAULT false,
    `image` MEDIUMTEXT NULL,
    `role` ENUM('STUDENT', 'TRAINER', 'ADMIN', 'OWNER', 'VENDOR') NOT NULL DEFAULT 'STUDENT',
    `status` ENUM('INVITATION_PENDING', 'PENDING_VERIFICATION', 'ACTIVE', 'TRIAL', 'PAYMENT_PENDING', 'PAYMENT_FAILED', 'GRACE_PERIOD', 'SUSPENDED', 'COMPLETED', 'CANCELLED', 'DEACTIVATED', 'ARCHIVED') NOT NULL DEFAULT 'PENDING_VERIFICATION',
    `currentRole` MEDIUMTEXT NULL,
    `experience` INTEGER NULL,
    `phone` MEDIUMTEXT NULL,
    `whatsapp` MEDIUMTEXT NULL,
    `country` MEDIUMTEXT NULL,
    `timezone` MEDIUMTEXT NULL,
    `marketingOptIn` BOOLEAN NOT NULL DEFAULT false,
    `termsAcceptedAt` DATETIME(3) NULL,
    `twoFactorEnabled` BOOLEAN NOT NULL DEFAULT false,
    `failedLoginCount` INTEGER NOT NULL DEFAULT 0,
    `lockedUntil` DATETIME(3) NULL,
    `lastLoginAt` DATETIME(3) NULL,
    `previousLoginAt` DATETIME(3) NULL,
    `lastLoginIp` MEDIUMTEXT NULL,
    `bannedAt` DATETIME(3) NULL,
    `lastSeenAt` DATETIME(3) NULL,
    `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updatedAt` DATETIME(3) NOT NULL,

    UNIQUE INDEX `User_email_key`(`email`),
    INDEX `User_role_idx`(`role`),
    INDEX `User_status_idx`(`status`),
    INDEX `User_createdAt_idx`(`createdAt`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

